export const localStorageService = {
  get: (key: string) => {
    const data = localStorage.getItem(key);
    if (data) return JSON.parse(data);
    return null;
  },
  set: (key: string, value: any) => {
    localStorage.setItem(key, JSON.stringify(value));
  },
  remove: (key: string) => {
    localStorage.removeItem(key);
  },
};
