import { apiUrls } from "../configs/apiUrl";
import { ArticleServer } from "../types/Article";
import { http } from "./http.service";

export const articlesService = {
  getAll: async () => {
    const url = apiUrls.articles;
    const { data } = await http.get<ArticleServer[] | null>(url);
    return data;
  },
  getById: async (id: string) => {
    const url = `${apiUrls.articles}/${id}`;

    const { data } = await http.get<ArticleServer | null>(url);
    return data;
  },
  createAndUpdate: async (payload: ArticleServer) => {
    const url = `${apiUrls.articles}/${payload.id}`;
    const { data } = await http.put<ArticleServer | null>(url, payload);
    return data;
  },
  getUserArticle: async (userId: string) => {
    const url = apiUrls.articles;
    const { data } = await http.get<ArticleServer[] | null>(url, {
      params: {
        orderBy: `"author"`,
        equalTo: `"${userId}"`,
      },
    });

    return data;
  },
  deleteArticleById: async (id: string) => {
    const url = `${apiUrls.articles}/${id}`;
    const { data } = await http.delete<null>(url);
    return data;
  },
};
